-- Ids are UUIDv7 generated by the backend (time ordered).
-- varchar(n) is stored exactly like text in PostgreSQL; the (n) only enforces a maximum length.

/*
 DATABASEDESIGN RULES:
 VARCHAR length is value in 2^x except for email (320)
 Explain fields with a '--' comment to the right. Describe the reason for the table at the bottom.
*/

CREATE TYPE session_kind AS ENUM ('web', 'app');
CREATE TYPE visibility AS ENUM ('public', 'private');   -- used by ideas and projects
CREATE TYPE notification_kind AS ENUM (
    'project_invite',       -- project_id: the owner invited you
    'join_request',         -- project_id: actor wants to join your project
    'request_accepted',     -- project_id: your join request was accepted
    'idea_comment',         -- idea_id + comment_id: someone commented on your idea
    'comment_reply',        -- idea_id + comment_id: someone replied to your comment
    'skill_vouch',          -- actor vouched for one of your skills
    'idea_shared',          -- idea_id: a private idea was shared with you
    'entrepreneur_vouch'    -- project_id: an admin vouched that you are entrepreneurial
);


-- ---------------------------------------------------------------- skills
CREATE TABLE skills (
    name        varchar(128) PRIMARY KEY
);
-- A list of all possible skills that users can have.

-- ---------------------------------------------------------------- identity

CREATE TABLE users (
    id             uuid PRIMARY KEY,
    entra_oid      uuid NOT NULL UNIQUE,
    tenant_id      uuid NOT NULL,
    email          varchar(320) NOT NULL,          -- RFC 5321 maximum
    display_name   varchar(256) NOT NULL,          -- Entra ID maximum
    bio            varchar(256) NOT NULL DEFAULT '',   -- short headline shown on the profile
    avatar_url     varchar(2048),                  -- NULL = app shows initials. From MS Graph photo or a MinIO upload
    is_admin      boolean NOT NULL DEFAULT false,
    created_at     timestamptz NOT NULL DEFAULT now(),
    last_login_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX users_email_idx ON users (lower(email));

CREATE TABLE user_skills (
    user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    skill       varchar(128) NOT NULL REFERENCES skills (name) ON DELETE RESTRICT,
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, skill)
);
/*
 skills that user claims they have.
*/

-- ---------------------------------------------------------------- identity end

CREATE TABLE sessions (
    id            uuid PRIMARY KEY,
    token_hash    bytea NOT NULL UNIQUE,
    user_id       uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    kind          session_kind NOT NULL,
    user_agent    varchar(256),                    -- truncated to 256 chars by the backend
    created_at    timestamptz NOT NULL DEFAULT now(),
    last_seen_at  timestamptz NOT NULL DEFAULT now(),
    expires_at    timestamptz NOT NULL
);
CREATE INDEX sessions_user_idx ON sessions (user_id);

-- In-flight OIDC logins (state -> nonce/PKCE). Single use, short lived.
-- state, nonce, pkce_verifier and code challenges are 43-char base64url values.
CREATE TABLE login_attempts (
    state               varchar(64) PRIMARY KEY,
    nonce               varchar(64) NOT NULL,
    pkce_verifier       varchar(128) NOT NULL,
    silent              boolean NOT NULL,
    return_to           varchar(2048) NOT NULL,
    app_redirect_uri    varchar(2048),              -- set for native app logins
    app_code_challenge  varchar(64),                -- app's own PKCE challenge, bound to the handoff code
    expires_at          timestamptz NOT NULL
);

-- One-time codes handed to the native app via its redirect URI.
CREATE TABLE app_handoffs (
    code_hash       bytea PRIMARY KEY,
    user_id         uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    code_challenge  varchar(64) NOT NULL,
    expires_at      timestamptz NOT NULL
);

-- A user's prospects: people they have marked as potential collaborators/partners.
-- One-way list managed by owner_id; private ideas can only be shared with the owner's prospects.
CREATE TABLE user_prospects (
    owner_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    prospect_id  uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_id, prospect_id),
    CHECK (owner_id <> prospect_id)
);
-- "Who has marked me as a prospect?"
CREATE INDEX user_prospects_prospect_idx ON user_prospects (prospect_id);

-- ---------------------------------------------------------------- projects

-- Created either directly, or from an idea (the idea is then linked via ideas.project_id).
-- The backend also inserts the owner into project_participants, so owners can hold roles (and be vouched for in them).
CREATE TABLE projects (
    id            uuid PRIMARY KEY,
    owner_id      uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name          varchar(128) NOT NULL,
    description   varchar(2048) NOT NULL DEFAULT '',
    -- public: everyone signed in. private: the owner plus the users in project_participants.
    visibility    visibility NOT NULL DEFAULT 'public',
    deadline      timestamptz default NULL,
    show_media    boolean NOT NULL DEFAULT false, -- Youtube videos linked to the project which will be shown on the project public page.
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX projects_owner_idx ON projects (owner_id);
-- Public feed, newest first.
CREATE INDEX projects_public_idx ON projects (created_at DESC) WHERE visibility = 'public';

CREATE TABLE project_media (
    id            uuid PRIMARY KEY,
    project_id    uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    url           varchar(2048) NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now()
);
-- URLs of the youtube videos
CREATE INDEX project_media_project_idx ON project_media (project_id);

CREATE TABLE project_roles (
    id            uuid PRIMARY KEY,
    project_id    uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    name          varchar(64) NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, name),   -- also serves "roles of this project" lookups
    UNIQUE (project_id, id)      -- target of project_participant_roles' (project_id, role_id) foreign key
);
-- Roles available in the project decided by the creator.
-- This allows the owner to create custom roles.
-- If someone requests to join the project the owner can create a custom role for them before adding them and then assigning them.

CREATE TABLE project_participant_requests (
    project_id   uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    user_id      uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (project_id, user_id)
);
/*
 requests from user's who want to participate in a project. 
 Can be from any signed-in user if project is public.
 If private it is only from the owner's prospects.
*/

CREATE TABLE project_invites (
    project_id   uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    user_id      uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (project_id, user_id)
);
-- "Project owner can invite prospects. This leads to a notification."

CREATE TABLE project_participants (
    project_id   uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    user_id      uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (project_id, user_id)
);
-- "Who is participating in this project?"

CREATE TABLE project_participant_roles (
    project_id   uuid NOT NULL,
    user_id      uuid NOT NULL,                    -- must be a participant of project_id
    role_id      uuid NOT NULL,                    -- must be a role of project_id
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (project_id, user_id, role_id),
    FOREIGN KEY (project_id, user_id) REFERENCES project_participants (project_id, user_id) ON DELETE CASCADE,
    FOREIGN KEY (project_id, role_id) REFERENCES project_roles (project_id, id) ON DELETE CASCADE
);
-- Roles assigned to a participant. The two composite foreign keys make the database enforce
-- that the user is a participant of the project and that the role belongs to the same project:
-- removing a participant or deleting a role removes the assignment.
-- "Who has this role?"
CREATE INDEX project_participant_roles_role_idx ON project_participant_roles (role_id);

CREATE TABLE project_categories (
    id           uuid PRIMARY KEY,
    project_id   uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    name         varchar(64) NOT NULL,             -- e.g. "Design", "Backend", "Marketing"
    created_at   timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, name),                     -- also serves "categories of this project" lookups
    UNIQUE (project_id, id)                        -- target of the (project_id, category_id) foreign keys below
);
-- Categories of work in a project, defined by the owner like project_roles.
-- Tasks are tagged with categories, and roles cover categories, which links tasks to the people who do them.

CREATE TABLE project_role_categories (
    project_id   uuid NOT NULL,
    role_id      uuid NOT NULL,                    -- must be a role of project_id
    category_id  uuid NOT NULL,                    -- must be a category of project_id
    PRIMARY KEY (project_id, role_id, category_id),
    FOREIGN KEY (project_id, role_id) REFERENCES project_roles (project_id, id) ON DELETE CASCADE,
    FOREIGN KEY (project_id, category_id) REFERENCES project_categories (project_id, id) ON DELETE CASCADE
);
-- The categories each role is responsible for. The composite foreign keys keep role and category
-- in the same project.
-- "Which roles cover this category?"
CREATE INDEX project_role_categories_category_idx ON project_role_categories (category_id);

CREATE TABLE project_tasks (
    id           uuid PRIMARY KEY,
    project_id   uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    position     integer NOT NULL CHECK (position >= 0),   -- order of the task in the project's sequence
    description  varchar(1024) NOT NULL,
    deadline     timestamptz NOT NULL,             -- estimated deadline set by the creator
    completed    boolean NOT NULL DEFAULT false,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),                       -- target of project_task_categories' (project_id, task_id) foreign key
    -- Deferred so tasks can be reordered by swapping positions inside one transaction.
    -- Also serves "tasks of this project in order" lookups.
    UNIQUE (project_id, position) DEFERRABLE INITIALLY DEFERRED
);
-- Sequential tasks of a project, done in position order.
-- Every task needs at least one category (project_task_categories); the backend inserts the task
-- and its categories in the same transaction.

CREATE TABLE project_task_categories (
    project_id   uuid NOT NULL,
    task_id      uuid NOT NULL,                    -- must be a task of project_id
    category_id  uuid NOT NULL,                    -- must be a category of project_id
    PRIMARY KEY (project_id, task_id, category_id),
    FOREIGN KEY (project_id, task_id) REFERENCES project_tasks (project_id, id) ON DELETE CASCADE,
    FOREIGN KEY (project_id, category_id) REFERENCES project_categories (project_id, id) ON DELETE CASCADE
);
-- The categories a task belongs to. Together with project_role_categories this answers
-- "which tasks can this role work on?". The composite foreign keys keep task and category in the same project.
-- "Tasks in this category"
CREATE INDEX project_task_categories_category_idx ON project_task_categories (category_id);

CREATE TABLE user_entrepreneurial_vouches (
    user_id      uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    project_id   uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    description  varchar(1024) NOT NULL,           -- what the user did that showed entrepreneurship
    voucher_id   uuid REFERENCES users (id) ON DELETE SET NULL,   -- must be an admin (enforced by the backend)
    PRIMARY KEY (user_id, project_id),
    CHECK (user_id <> voucher_id)                  -- no vouching for yourself; passes when voucher_id is NULL
);
/*
    This is what determines if the user is an entrepreneur or not.
    Only admins can vouch that a user is entrepreneurial.
*/

CREATE TABLE skill_vouches (
    user_id     uuid NOT NULL,                     -- the user being vouched for
    skill       varchar(128) NOT NULL,             -- must be a skill user_id claims (user_skills)
    voucher_id  uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,   -- the user vouching
    project_id  uuid,                              -- project where the voucher saw the skill. Required on insert (backend)
    role_id     uuid,                              -- role user_id held in project_id. NULL = assignment/project later removed
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, skill, voucher_id),
    FOREIGN KEY (user_id, skill) REFERENCES user_skills (user_id, skill) ON DELETE CASCADE,
    -- The role must be one user_id actually held in that project.
    FOREIGN KEY (project_id, user_id, role_id)
        REFERENCES project_participant_roles (project_id, user_id, role_id)
        ON DELETE SET NULL (project_id, role_id),
    CHECK ((project_id IS NULL) = (role_id IS NULL)),
    CHECK (user_id <> voucher_id)                  -- no vouching for yourself
);
/*
    A user vouches that another user has a skill, based on the role that user played in a project.
    The backend requires project_id and role_id on insert, and only accepts the vouch when the voucher
    is the project's owner or a participant (a teammate), or an admin.
    If the role assignment or the project is removed later, project_id and role_id become NULL:
    the vouch still counts, it just no longer points at a role.
    Removing a skill from user_skills removes its vouches.
    Used to show who vouched for each skill, and in what role, on the user's profile.
*/
-- "Vouches I have given"
CREATE INDEX skill_vouches_voucher_idx ON skill_vouches (voucher_id);
-- Finds the vouches to clear when a role assignment is deleted.
CREATE INDEX skill_vouches_role_idx ON skill_vouches (project_id, user_id, role_id) WHERE project_id IS NOT NULL;

-- ---------------------------------------------------------------- ideas

CREATE TABLE idea_comment_types (
    id            uuid PRIMARY KEY,
    label         varchar(32) NOT NULL UNIQUE,
    color         varchar(8) NOT NULL CHECK (color ~ '^#[0-9A-Fa-f]{6}$')    -- e.g. #3C87F7
);

CREATE TABLE ideas (
    id            uuid PRIMARY KEY,
    user_id       uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    title         varchar(128) NOT NULL,
    description   varchar(2048) NOT NULL,
    -- public: everyone signed in. private: the owner plus the users in idea_shares.
    visibility    visibility NOT NULL DEFAULT 'public',
    -- Set when the idea became (or was attached to) a project. Deleting the project keeps
    -- the idea and just unlinks it.
    project_id    uuid REFERENCES projects (id) ON DELETE SET NULL,
    vote_count    integer NOT NULL DEFAULT 0,     -- cached count of idea_votes, for sorting
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id, user_id)    -- target of idea_shares' (idea_id, owner_id) foreign key
);
-- Public feed, newest first.
CREATE INDEX ideas_public_idx ON ideas (created_at DESC) WHERE visibility = 'public';
-- Public feed, most upvoted first.
CREATE INDEX ideas_public_top_idx ON ideas (vote_count DESC, created_at DESC) WHERE visibility = 'public';
CREATE INDEX ideas_user_idx ON ideas (user_id);
-- "Which ideas belong to this project?"
CREATE INDEX ideas_project_idx ON ideas (project_id) WHERE project_id IS NOT NULL;

-- Who may view a private idea. The two composite foreign keys make the database enforce
-- that the viewer is a prospect of the idea's owner: removing someone from your prospects
-- revokes their access to all your private ideas.
CREATE TABLE idea_shares (
    idea_id     uuid NOT NULL,
    owner_id    uuid NOT NULL,
    user_id     uuid NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (idea_id, user_id),
    FOREIGN KEY (idea_id, owner_id) REFERENCES ideas (id, user_id) ON DELETE CASCADE,
    FOREIGN KEY (owner_id, user_id) REFERENCES user_prospects (owner_id, prospect_id) ON DELETE CASCADE
);
-- "Ideas shared with me".
CREATE INDEX idea_shares_user_idx ON idea_shares (user_id);

CREATE TABLE idea_votes (
    idea_id     uuid NOT NULL REFERENCES ideas (id) ON DELETE CASCADE,
    user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (idea_id, user_id)
);
-- One upvote per user per idea. Keep ideas.vote_count in sync in the same transaction.
-- "Ideas I upvoted"
CREATE INDEX idea_votes_user_idx ON idea_votes (user_id);

-- Reddit-style threaded comments: parent_id points at the comment being replied to
-- (NULL = top-level). Deleted comments are soft-deleted so their replies keep their place;
-- the API shows them as "[deleted]".
CREATE TABLE idea_comments (
    id            uuid PRIMARY KEY,
    idea_id       uuid NOT NULL REFERENCES ideas (id) ON DELETE CASCADE,
    parent_id     uuid,
    user_id       uuid REFERENCES users (id) ON DELETE SET NULL,   -- NULL = author deleted their account
    comment_type  uuid NOT NULL REFERENCES idea_comment_types (id),
    content       varchar(512) NOT NULL,
    depth         smallint NOT NULL DEFAULT 0 CHECK (depth BETWEEN 0 AND 10),  -- parent's depth + 1
    score         integer NOT NULL DEFAULT 0,  -- cached sum of idea_comment_votes.value, for sorting
    deleted_at    timestamptz,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),

    UNIQUE (idea_id, id),
    -- A reply must belong to the same idea as its parent. Skipped when parent_id is NULL.
    FOREIGN KEY (idea_id, parent_id) REFERENCES idea_comments (idea_id, id),
    CHECK ((parent_id IS NULL) = (depth = 0))
);
-- Loading a thread: every comment of an idea, grouped by parent.
CREATE INDEX idea_comments_thread_idx ON idea_comments (idea_id, parent_id, created_at);
-- Finding the replies of a comment (recursive "load more replies" query).
CREATE INDEX idea_comments_parent_idx ON idea_comments (parent_id) WHERE parent_id IS NOT NULL;

-- One up/down vote per user per comment. Keep idea_comments.score in sync in the same transaction.
CREATE TABLE idea_comment_votes (
    comment_id  uuid NOT NULL REFERENCES idea_comments (id) ON DELETE CASCADE,
    user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    value       smallint NOT NULL CHECK (value IN (-1, 1)),
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (comment_id, user_id)
);
CREATE INDEX idea_comment_votes_user_idx ON idea_comment_votes (user_id);

-- ---------------------------------------------------------------- problems

CREATE TABLE problems (
    id            uuid PRIMARY KEY,
    user_id       uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    title         varchar(128) NOT NULL,
    description   varchar(1024) NOT NULL,
    vote_count    integer NOT NULL DEFAULT 0,     -- cached count of problem_votes ("me too"), for sorting
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX problems_user_idx ON problems (user_id);
-- Feed, newest first.
CREATE INDEX problems_new_idx ON problems (created_at DESC);
-- Feed, most "me too" votes first.
CREATE INDEX problems_top_idx ON problems (vote_count DESC, created_at DESC);

CREATE TABLE problem_votes (
    problem_id  uuid NOT NULL REFERENCES problems (id) ON DELETE CASCADE,
    user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (problem_id, user_id)
);
-- "Me too" votes: users saying they have this problem as well.
-- Keep problems.vote_count in sync in the same transaction.
-- "Problems I voted on"
CREATE INDEX problem_votes_user_idx ON problem_votes (user_id);

CREATE TABLE idea_problem_links (
    problem_id  uuid NOT NULL REFERENCES problems (id) ON DELETE CASCADE,
    idea_id     uuid NOT NULL REFERENCES ideas (id) ON DELETE CASCADE,
    description   varchar(128) NOT NULL,
    PRIMARY KEY (problem_id, idea_id)
);
CREATE INDEX idea_problem_links_idea_idx ON idea_problem_links (idea_id);

-- ---------------------------------------------------------------- notifications

CREATE TABLE notifications (
    id          uuid PRIMARY KEY,
    user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,      -- recipient
    actor_id    uuid REFERENCES users (id) ON DELETE SET NULL,              -- who caused it. NULL = account deleted
    kind        notification_kind NOT NULL,
    problem_id  uuid REFERENCES problems (id) ON DELETE CASCADE,
    idea_id     uuid REFERENCES ideas (id) ON DELETE CASCADE,
    project_id  uuid REFERENCES projects (id) ON DELETE CASCADE,
    comment_id  uuid REFERENCES idea_comments (id) ON DELETE CASCADE,
    read_at     timestamptz,                                                -- NULL = unread
    created_at  timestamptz NOT NULL DEFAULT now()
);
/*
 The user's inbox. Written by the backend in the same transaction as the event that causes it.
 Which of problem_id / idea_id / project_id / comment_id is set depends on kind (see notification_kind).
 Deleting the linked entity removes the notification.
*/
-- Inbox, newest first.
CREATE INDEX notifications_user_idx ON notifications (user_id, created_at DESC);
-- Unread badge count.
CREATE INDEX notifications_unread_idx ON notifications (user_id) WHERE read_at IS NULL;
